suppressMessages({library(dplyr);library(tidyr)}); options(width=250, dplyr.print_max=400)
d <- "data/state_elections/final/"
u <- readRDS(paste0(d,"state_unharm.rds")); w <- readRDS(paste0(d,"ltw_wkr_unharm.rds")); wl <- readRDS(paste0(d,"ltw_wkr_unharm_long.rds"))
print(sapply(w[c("eligible_voters","number_voters","valid_votes","invalid_votes","turnout","spd","cdu","afd")], function(x) c(min=min(x,na.rm=T), max=max(x,na.rm=T), nNA=sum(is.na(x)))))
s <- function(x) if (all(is.na(x))) NA_real_ else sum(x, na.rm=TRUE)
a <- u %>% group_by(state, election_year, election_date) %>% summarise(n_u=n(), ev_u=s(eligible_voters), nv_u=s(number_voters), vv_u=s(valid_votes), iv_u=s(invalid_votes), .groups="drop")
b <- w %>% filter(stimme %in% c("zweitstimme","einzelstimme")) %>% group_by(state, election_year, election_date, stimme) %>% summarise(n_w=n(), ev_w=s(eligible_voters), nv_w=s(number_voters), vv_w=s(valid_votes), iv_w=s(invalid_votes), .groups="drop")
m <- inner_join(a,b,by=c("state","election_year","election_date")) %>% mutate(d_ev=ev_w/ev_u-1, d_nv=nv_w/nv_u-1, d_vv=vv_w/vv_u-1, d_iv=iv_w/iv_u-1)
cat("matched state-elections:", nrow(m), "; wkr state-elections (zweit/einzel):", nrow(b), "; unmatched wkr:\n"); print(anti_join(b,a,by=c("state","election_year","election_date")) %>% as.data.frame())
cat("\nDeviations >0.1% in ev/nv/vv:\n")
print(m %>% filter(abs(d_ev)>0.001|abs(d_nv)>0.001|abs(d_vv)>0.001) %>% select(state,election_year,stimme,n_u,n_w,ev_u,ev_w,d_ev,nv_u,nv_w,d_nv,vv_u,vv_w,d_vv) %>% mutate(across(starts_with("d_"),~round(.x,4))) %>% as.data.frame())
cat("\nNA mismatch: u NA vs w non-NA, or vice versa\n")
print(m %>% filter(is.na(ev_u)!=is.na(ev_w)|is.na(nv_u)!=is.na(nv_w)|is.na(vv_u)!=is.na(vv_w)) %>% select(state,election_year,stimme,ev_u,ev_w,nv_u,nv_w,vv_u,vv_w) %>% as.data.frame())
saveRDS(m, file.path(dirname(sub("--file=","",grep("--file=",commandArgs(),value=TRUE))),"wkr_tot.rds"))
